(()=>{var global=hugerte.util.Tools.resolve("hugerte.PluginManager");let setContent=(editor,html)=>{editor.focus(),editor.undoManager.transact(()=>{editor.setContent(html)}),editor.selection.setCursorLocation(),editor.nodeChanged()},getContent=editor=>editor.getContent({source_view:!0}),open=editor=>{var editorContent=getContent(editor);editor.windowManager.open({title:"Source Code",size:"large",body:{type:"panel",items:[{type:"textarea",name:"code"}]},buttons:[{type:"cancel",name:"cancel",text:"Cancel"},{type:"submit",name:"save",text:"Save",primary:!0}],initialData:{code:editorContent},onSubmit:api=>{setContent(editor,api.getData().code),api.close()}})};global.add("code",editor=>((editor=>{editor.addCommand("mceCodeEditor",()=>{open(editor)})})(editor),(editor=>{var onAction=()=>editor.execCommand("mceCodeEditor");editor.ui.registry.addButton("code",{icon:"sourcecode",tooltip:"Source code",onAction:onAction}),editor.ui.registry.addMenuItem("code",{icon:"sourcecode",text:"Source code",onAction:onAction})})(editor),{}))})();